#!/usr/bin/env node
// Packaging invariants that a published install depends on and nothing else compares:
//  - the napi loader (generated by `napi build`, committed) compares the version of the
//    binding packages it loads with its own package.json, not a literal that a version
//    bump leaves stale (a stale pin makes NAPI_RS_ENFORCE_VERSION_CHECK reject the right
//    binary). `scripts/napi-loader-version.mjs` rewrites the literal after the build.
//  - every CLI linux-*-gnu package declares `libc: ["glibc"]` like the napi ones, so
//    package managers do not hand the glibc binary to a musl host.
// Regenerate the loader with `pnpm --filter caliper-docgen-napi build:napi`.
import { readFileSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const readJson = (path) => JSON.parse(readFileSync(join(root, path), 'utf8'))

const problems = []

const loader = readFileSync(join(root, 'packages/napi/index.js'), 'utf8')
const literalPins = new Set([...loader.matchAll(/bindingPackageVersion !== '([^']+)'/g)].map((m) => m[1]))
for (const pin of literalPins) {
  problems.push(
    `packages/napi/index.js pins binding version ${pin} as a literal that a version bump leaves stale; run \`pnpm --filter caliper-docgen-napi build:napi\``,
  )
}
if (!loader.includes("bindingPackageVersion !== require('./package.json').version")) {
  problems.push('packages/napi/index.js does not compare the binding version with its own package.json version')
}

for (const dir of ['packages/cli/npm', 'packages/napi/npm']) {
  for (const name of readdirSync(join(root, dir)).filter((n) => n.endsWith('-gnu'))) {
    const libc = readJson(`${dir}/${name}/package.json`).libc
    if (JSON.stringify(libc) !== '["glibc"]') {
      problems.push(`${dir}/${name}/package.json has libc ${JSON.stringify(libc)}, expected ["glibc"]`)
    }
  }
}

if (problems.length > 0) {
  process.stderr.write(`${problems.join('\n')}\n`)
  process.exit(1)
}
